use spore_core::{creature_skin_seed_v1::seed,native_sse::Policy};use std::io::Write;
fn main(){let mut out=Vec::new();for case in 0..6 {let mut groups=[[[0.;3];4];1];if case==1{groups[0][1]=[2.,0.,0.]}if case==5{groups[0][0]=[0.,0.,255.]};let extent=if case==3{[255.,1.,1.]}else{[2.;3]};let n=if case==4{0}else{1};let empty=[];let inputs=if n==0{&empty[..]}else{&groups[..]};let mut log=Vec::new();let r=seed(extent,[0.;3],1.,1.,inputs,n,Policy::Mxcsr1f80,|p|{log.push(p);let k=log.len();match case{0=>1.5-p[2],1=>if k==9{0.}else{-1.},2=>if k==130{-1.}else{0.},5=>if k==1{0.}else{-1.},_=>panic!("unexpected callback")}});assert!(log.len()<=130);for x in [u32::from(r.is_ok()),r.unwrap_or(u32::MAX),log.len() as u32]{out.extend(x.to_le_bytes())}for i in 0..130{for v in log.get(i).copied().unwrap_or([0.;3]){out.extend(v.to_bits().to_le_bytes())}}}std::io::stdout().write_all(&out).unwrap();}
